insert into stores (id,name,slug) values ('11111111-1111-1111-1111-111111111111','Matriz Manoel','manoel'),('22222222-2222-2222-2222-222222222222','Brilhante','brilhante');
insert into categories (name,icon,sort_order) values ('Carnes e Proteínas','🥩',1),('Frios e Queijos','🧀',2),('Hortifruti','🥬',3),('Congelados','🧊',4),('Mercado','🛒',5),('Embalagens','📦',6),('Limpeza','🧽',7),('Molhos','🍯',8),('Temperos','🧂',9),('Sobremesas','🍰',10),('Bebidas','🍺',11),('Descartáveis','🥤',12),('Outros','🔧',13);
insert into products (id,name,category_id,unit,purchase_unit,weight_per_unit_g,yield_units) select '33333333-3333-3333-3333-333333333333','Hambúrguer Tradicional',id,'un','kg',110,95 from categories where name='Carnes e Proteínas';
insert into products (name,category_id,unit) select 'Picadinho',id,'un' from categories where name='Carnes e Proteínas' union all select 'Filé de Frango',id,'un' from categories where name='Carnes e Proteínas' union all select 'Mussarela',id,'kg' from categories where name='Frios e Queijos' union all select 'Presunto',id,'kg' from categories where name='Frios e Queijos' union all select 'Alface',id,'cx' from categories where name='Hortifruti' union all select 'Tomate',id,'cx' from categories where name='Hortifruti';
insert into inventory (store_id,product_id,current_qty,min_qty,ideal_qty) values ('11111111-1111-1111-1111-111111111111','33333333-3333-3333-3333-333333333333',45,30,95),('22222222-2222-2222-2222-222222222222','33333333-3333-3333-3333-333333333333',72,30,95);
insert into inventory (store_id,product_id,current_qty,min_qty,ideal_qty) select s.id,p.id,10,5,20 from stores s cross join products p where p.name!='Hambúrguer Tradicional';
